def eval_expression(expr: str) -> float:
    """
    Evaluate a mathematical expression string with support for:
    - Addition, subtraction, multiplication, division
    - Parentheses
    - Negative numbers
    Follows standard order of operations (PEMDAS/BODMAS).
    Raises ZeroDivisionError if division by zero is encountered.
    """
    expr = expr.strip()

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isspace():
            i += 1
            continue
        if char in '+-*/()':
            tokens.append(char)
            i += 1
        else:
            # Parse number (integer or float, possibly negative)
            j = i
            is_negative = False
            if char == '-':
                # Check if this is a unary minus (negative number)
                # It's unary if at the start, after '(', or after an operator
                if i == 0 or (i > 0 and expr[i-1] in '(+-*/'):
                    # Check if next char is a digit or dot
                    if i + 1 < len(expr) and (expr[i+1].isdigit() or expr[i+1] == '.'):
                        j = i + 1
                        is_negative = True
                    else:
                        tokens.append('-')
                        i += 1
                        continue
                else:
                    tokens.append('-')
                    i += 1
                    continue
            # Now parse the number starting at j
            num_str = ''
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                num_str += expr[j]
                j += 1
            if not num_str:
                raise ValueError(f"Invalid character at position {i}: {char}")
            number = float(num_str)
            if is_negative:
                number = -number
            tokens.append(number)
            i = j

    # Recursive descent parser
    # Grammar:
    # expression = term (('+' | '-') term)*
    # term = factor (('*' | '/') factor)*
    # factor = NUMBER | '(' expression ')' | ('+' | '-') factor

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.tokens[self.pos]
            self.pos += 1
            return token

        def parse(self):
            result = self.expression()
            if self.pos != len(self.tokens):
                raise ValueError("Unexpected token")
            return result

        def expression(self):
            result = self.term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.term()
                if op == '+':
                    result += right
                else:
                    result -= right
            return result

        def term(self):
            result = self.factor()
            while self.peek() in ('*', '/'):
                op = self.consume()
                right = self.factor()
                if op == '*':
                    result *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    result /= right
            return result

        def factor(self):
            token = self.peek()

            # Handle unary operators
            if token == '+':
                self.consume()
                return self.factor()
            if token == '-':
                self.consume()
                return -self.factor()

            if token == '(':
                self.consume()
                result = self.expression()
                if self.peek() != ')':
                    raise ValueError("Expected closing parenthesis")
                self.consume()
                return result

            if isinstance(token, float):
                self.consume()
                return token

            raise ValueError(f"Unexpected token: {token}")

    parser = Parser(tokens)
    result = parser.parse()

    # Return as int if the result is a whole number
    if result == int(result):
        return int(result)
    return result
